#include <vector>
#include <algorithm>

// Compute the maximum total cost by partitioning the vector into contiguous subarrays.
// In each subarray, the first element is added; all subsequent elements are subtracted.
// Returns the maximum possible sum (as long long).
long long maximumTotalCost(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    // prev0: max cost for suffix starting at current index when current is the first element of a subarray.
    // prev1: max cost for suffix starting at current index when current is NOT the first element of a subarray.
    long long prev0 = 0, prev1 = 0;

    for (int i = n - 1; i >= 0; --i) {
        // If current is not first, we can either subtract it and have the next as first,
        // or add it and have the next as not first (whichever is better). Since it's not first,
        // both signs are allowed.
        long long cur1 = std::max(-static_cast<long long>(nums[i]) + prev0,
                                  static_cast<long long>(nums[i]) + prev1);
        // If current is first, it must be added. The next element can only be a continuation
        // (not first) because prev1 >= prev0 always holds; using prev1 gives the optimal choice.
        long long cur0 = static_cast<long long>(nums[i]) + prev1;

        prev0 = cur0;
        prev1 = cur1;
    }
    // The entire array's first element is always the first of a subarray, so use prev0.
    return prev0;
}

#include <cassert>
